def configurar_tipos_e_unificar_agendas_ativas(apps, schema_editor):
    db = schema_editor.connection.alias
    TipoAgendamento = apps.get_model('agenda_pacientes', 'TipoAgendamento')
    AgendaPaciente = apps.get_model('agenda_pacientes', 'AgendaPaciente')

    for tipo in TipoAgendamento.objects.using(db).select_related(
            'local__setor__ala').order_by('pk'):
        agendas = AgendaPaciente.objects.using(db).filter(
            tipo_id=tipo.pk, status='A').select_related('local__setor__ala')
        locais = list(agendas)
        local_referencia = tipo.local
        if not local_referencia:
            local_referencia = next(
                (agenda.local for agenda in locais if agenda.local_id), None)

        ala_internacao = bool(
            local_referencia
            and local_referencia.setor_id
            and local_referencia.setor.ala_id
            and local_referencia.setor.ala.internacao
        )
        tipo.externo = not ala_internacao
        tipo.exige_exame_solicitado = (
            'exame' in tipo.descricao.lower()
            or any(agenda.exame_id for agenda in locais)
        )
        tipo.save(
            using=db,
            update_fields=['externo', 'exige_exame_solicitado'],
        )

    agendas_por_exame = {}
    for agenda in AgendaPaciente.objects.using(db).filter(
            status='A', exame__isnull=False).order_by(
                'exame_id', 'data_hora', 'pk'):
        agendas_por_exame.setdefault(agenda.exame_id, []).append(agenda.pk)
    for agenda_ids in agendas_por_exame.values():
        if len(agenda_ids) > 1:
            AgendaPaciente.objects.using(db).filter(
                pk__in=agenda_ids[1:]).update(status='I')


